import fs from 'node:fs/promises';
import path from 'node:path';
import { unstable_cache } from 'next/cache';

const DB_PATH = path.join(process.cwd(), 'posts.json');

export type Post = {
  id: string;
  title: string;
  content: string;
  createdAt: string;
};

// Initialize DB if not exists
async function initDB() {
  try {
    await fs.access(DB_PATH);
  } catch {
    await fs.writeFile(DB_PATH, JSON.stringify([]));
  }
}

async function getPostsUncached(): Promise<Post[]> {
  await initDB();
  const data = await fs.readFile(DB_PATH, 'utf-8');
  return JSON.parse(data);
}

// Cached version of getPosts
export const getPosts = unstable_cache(
  async () => {
    return getPostsUncached();
  },
  ['posts-cache-key'], // keyParts
  {
    tags: ['posts'], // cache tags
    revalidate: 3600,
  }
);

export async function addPost(title: string, content: string) {
  await initDB();
  const posts = await getPostsUncached();
  const newPost: Post = {
    id: Date.now().toString(),
    title,
    content,
    createdAt: new Date().toISOString(),
  };
  posts.push(newPost);
  await fs.writeFile(DB_PATH, JSON.stringify(posts, null, 2));
  return newPost;
}

'use server';

import { updateTag } from 'next/cache';
import { addPost } from './lib/data';
import { redirect } from 'next/navigation';

export async function createPost(formData: FormData) {
  const title = formData.get('title') as string;
  const content = formData.get('content') as string;

  if (!title || !content) {
    throw new Error('Title and content are required');
  }

  await addPost(title, content);

  // Invalidate the cache for the 'posts' tag immediately
  updateTag('posts');

  redirect('/');
}

